local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)
local ServiceDescriptorImplementationTypeResolver = require(script.Parent.ServiceDescriptorImplementationTypeResolver)
local ServiceProvider = require(script.Parent.ServiceProvider)
local XpCallHelper = require(script.Parent.XpCallHelper)

local ServiceDescriptorResolver = {}

function ServiceDescriptorResolver.Resolve(
	serviceProvider: ServiceProvider,
	service,
	descriptor: ServiceDescriptor,
	unsolved: { string },
	luaTypeProvider
)
	if descriptor.Lifetime == ServiceLifetime.Transient then
		local result =
			ServiceDescriptorResolver._resolveNoCache(serviceProvider, service, descriptor, unsolved, luaTypeProvider)
		return result
	elseif descriptor.Lifetime == ServiceLifetime.Singleton then
		if serviceProvider.IsRoot then
			return ServiceDescriptorResolver._cache(serviceProvider, service, descriptor, unsolved, luaTypeProvider)
		end
		return ServiceDescriptorResolver.Resolve(serviceProvider.Parent, service, descriptor, unsolved, luaTypeProvider)
	else
		return ServiceDescriptorResolver._cache(serviceProvider, service, descriptor, unsolved, luaTypeProvider)
	end
end

function ServiceDescriptorResolver._cache(serviceProvider, service, descriptor, unsolved: { string }, luaTypeProvider)
	local has, result = serviceProvider:TryGetCachedService(descriptor, service)
	if has then
		return result
	end

	local success, result = pcall(function()
		result =
			ServiceDescriptorResolver._resolveNoCache(serviceProvider, service, descriptor, unsolved, luaTypeProvider)

		return result
	end)
	if not success then
		local message = nil
		if result.message then
			message = result.message
		else
			message = result
		end
		error(message, 0)
	end

	if not result then
		return nil
	end

	serviceProvider:AddCache(descriptor, service, result)
	serviceProvider:AddCreatedObjectHistory(descriptor, result)

	return result
end

function ServiceDescriptorResolver._resolveNoCache(
	serviceProvider,
	service,
	descriptor,
	unsolved: { string },
	luaTypeProvider
)
	if descriptor.ImplementationInstance then
		return descriptor.ImplementationInstance
	end
	if descriptor.ImplementationFactory then
		return XpCallHelper.call(function()
			return descriptor.ImplementationFactory(serviceProvider)
		end, 1, `error on resolve serviceFactory '{service}' \n`)
	end
	if not descriptor.ImplementationType then
		error("impossible")
	end
	local implementationType = descriptor.ImplementationType
	local serviceType = descriptor.ServiceType
	return ServiceDescriptorImplementationTypeResolver.ResolveFromImplementationType(
		serviceProvider,
		service,
		implementationType,
		serviceType,
		unsolved,
		luaTypeProvider
	)
end

return ServiceDescriptorResolver
